import { MeshBasicNodeMaterial } from 'three/webgpu';

export default function createNode(config, ctx) {
  const { Group, Mesh, PlaneGeometry } = ctx.THREE;

  // Root container
  const root = new Group();

  // Geometry for the card plane (default size 2 x 1 units)
  const geometry = new PlaneGeometry(2, 1);
  // Basic material – will receive the loaded texture
  const material = new MeshBasicNodeMaterial({ color: 0xffffff });

  // Mesh assembly
  const mesh = new Mesh(geometry, material);
  root.add(mesh);

  // Load the texture asynchronously; assign when ready
  let loadedTexture = null;
  const texturePromise = ctx.textureLoader
    .loadTexture(config.imageUrl)
    .then((tex) => {
      loadedTexture = tex;
      material.map = tex;
      material.needsUpdate = true;
    })
    .catch(() => {
      // Silently ignore texture load failures
    });

  // Prepare userData for external interaction
  root.userData.handlers = {};
  root.userData.cleanup = () => {
    // Dispose geometry and material
    geometry.dispose();
    material.dispose();

    // Dispose texture if it was loaded
    if (loadedTexture) {
      loadedTexture.dispose();
    }

    // Kill any pending GSAP timelines (none in this node)
    // (placeholder for future timelines)
  };

  // Store references to aid cleanup and possible future extensions
  root.__prism = {
    texturePromise,
    material,
    geometry,
    mesh,
  };

  return root;
}
